using System.IO;
using System.Text.RegularExpressions;

namespace ZZZwallpaper.InstallerPreview;

internal sealed record PersonalDataCleanupResult(int DeletedFiles, int FailedItems);

// Delete only files generated by this application, never an entire profile tree
// or paths read from the media database. Unknown files and original videos stay.
internal static class PersonalDataCleanup
{
    internal static PersonalDataCleanupResult RemoveCurrentUserData() => RemoveKnownData(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), Path.GetTempPath());

    internal static PersonalDataCleanupResult RemoveKnownData(string localApplicationData, string temporaryDirectory)
    {
        var deleted = 0; var failed = 0;
        void Clean(string parent, string ownedName, (string Folder, Func<string, bool> Owned)[] rules)
        {
            if (!Path.IsPathFullyQualified(parent)) throw new ArgumentException("An absolute data parent is required.");
            var parentPath = Path.TrimEndingDirectorySeparator(Path.GetFullPath(parent));
            var root = Path.GetFullPath(Path.Combine(parentPath, ownedName));
            if (!root.StartsWith(parentPath + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("Data cleanup escaped its explicit parent.");
            if (!Directory.Exists(root)) return;
            try { RequireNoLinks(root); }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { failed++; return; }

            // Deepest known directory first, without recursive enumeration/deletion.
            foreach (var rule in rules)
            {
                var folder = rule.Folder.Length == 0 ? root : Path.GetFullPath(Path.Combine(root, rule.Folder));
                if (folder != root && !folder.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException("Data cleanup escaped its owned directory.");
                if (!Directory.Exists(folder)) continue;
                try
                {
                    RequireNoLinks(folder);
                    foreach (var file in Directory.EnumerateFiles(folder))
                    {
                        if (!rule.Owned(Path.GetFileName(file))) continue;
                        try
                        {
                            RequireNoLinks(folder);
                            if ((File.GetAttributes(file) & FileAttributes.ReparsePoint) != 0) { failed++; continue; }
                            File.Delete(file);
                            if(File.Exists(file))failed++;else deleted++;
                        }
                        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { failed++; }
                    }
                    RequireNoLinks(folder);
                    if (!Directory.EnumerateFileSystemEntries(folder).Any()) Directory.Delete(folder, recursive: false);
                }
                catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { failed++; }
            }
        }

        static bool Match(string value, string pattern) => Regex.IsMatch(value, pattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        static bool Log(string name) => name.StartsWith("zzzwallpaper-", StringComparison.OrdinalIgnoreCase) && name.EndsWith(".jsonl", StringComparison.OrdinalIgnoreCase);
        Clean(localApplicationData, "LumaWall", [
            (Path.Combine("effect-preview", "cache"), name => Match(name, @"^[0-9a-f]{32}\.bmp$")),
            ("effect-preview", name => Match(name, @"^custom-[0-9a-f]{32}\.(png|jpe?g|bmp|gif|webp|tiff?)$")),
            ("posters", name => Match(name, @"^[0-9a-f]{32}\.bmp$")),
            ("logs", Log),
            ("diagnostics", name => name is "menu-surface.png" or "menu-render.json" or "menu-lifecycle.json"),
            ("", name => name is "library.db" or "library.db-wal" or "library.db-shm" or "library.db-journal" or "desktop-diagnostics.json")
        ]);
        Clean(temporaryDirectory, "ZZZwallpaper-masks", [
            ("", name => Match(name, @"^([0-9a-f]{64}\.mask|[0-9a-f]{32}\.tmp)$"))
        ]);
        Clean(temporaryDirectory, "ZZZwallpaper", [("logs", Log), ("", _ => false)]);
        return new(deleted, failed);
    }

    private static void RequireNoLinks(string directory)
    {
        for (var node = new DirectoryInfo(directory); node is not null; node = node.Parent)
            if (node.Exists && (node.Attributes & FileAttributes.ReparsePoint) != 0)
                throw new IOException("Linked data directories are preserved.");
    }
}
